-- SOV Oružarstvo v2.1 / Build 1
-- Opening balance import: Inventura Klaićeva 2026
-- Source XLS: sov_popis_iz_fotki_dopunjeno_crveno_nesigurno.xlsx
--
-- VAŽNO:
-- - Ovo je SQL-only build.
-- - Ne dira web, APK, auth, posudbe, zahtjeve ni stare povijesne zapise.
-- - XLS inventura Klaićeva postaje službeno početno stanje.
-- - Prethodni XLS seed redovi se NE brišu fizički; označavaju se kao superseded i skrivaju,
--   da ne ostanu aktivni duplikati, ali da ne riskiramo foreign key/povijest.
-- - Stavke sa statusom "Provjeriti" ulaze u bazu kao fizički postojeće, ali nisu dostupne članovima.
--
-- Nakon pokretanja provjeri summary SELECT na dnu.

begin;

create extension if not exists pgcrypto;

-- 1) Core tables/columns, conservative and idempotent.
create table if not exists public.equipment_categories (
  id uuid primary key default gen_random_uuid(),
  legacy_id text unique,
  name text not null,
  description text,
  type text,
  sort_order integer,
  updated_at timestamptz not null default now()
);

create table if not exists public.equipment_locations (
  id uuid primary key default gen_random_uuid(),
  legacy_id text unique,
  name text not null,
  description text,
  type text
);

create table if not exists public.equipment_items (
  id uuid primary key default gen_random_uuid(),
  legacy_id text unique,
  catalog_id text,
  name text not null,
  category_id text,
  category_name text,
  subcategory text,
  unit text default 'kom',
  tracking_type text,
  quantity numeric default 0,
  loaned numeric default 0,
  available numeric default 0,
  minimum numeric,
  status text default 'aktivno',
  availability text default 'dostupno',
  member_visible boolean not null default true,
  internal_note text,
  source_sheet text,
  item_kind text,
  code_required boolean not null default false,
  physical_code_note text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

alter table public.equipment_items
  add column if not exists catalog_id text,
  add column if not exists category_id text,
  add column if not exists category_name text,
  add column if not exists subcategory text,
  add column if not exists unit text default 'kom',
  add column if not exists tracking_type text,
  add column if not exists quantity numeric default 0,
  add column if not exists loaned numeric default 0,
  add column if not exists available numeric default 0,
  add column if not exists minimum numeric,
  add column if not exists status text default 'aktivno',
  add column if not exists availability text default 'dostupno',
  add column if not exists member_visible boolean not null default true,
  add column if not exists internal_note text,
  add column if not exists location_name text default 'Oružarstvo Klaićeva',
  add column if not exists source_sheet text,
  add column if not exists item_kind text,
  add column if not exists code_required boolean not null default false,
  add column if not exists physical_code_note text,
  add column if not exists quantity_label text,
  add column if not exists available_label text,
  add column if not exists last_inventory_date date,
  add column if not exists source_xls_row integer,
  add column if not exists xls_category text,
  add column if not exists xls_subcategory text,
  add column if not exists original_quantity_text text,
  add column if not exists created_at timestamptz not null default now(),
  add column if not exists updated_at timestamptz not null default now();

create unique index if not exists equipment_items_legacy_id_uq on public.equipment_items(legacy_id);
create index if not exists equipment_items_klaiceva_source_idx on public.equipment_items(source_sheet);
create index if not exists equipment_items_klaiceva_category_idx on public.equipment_items(category_name, subcategory);

create table if not exists public.equipment_item_locations (
  id uuid primary key default gen_random_uuid(),
  equipment_legacy_id text,
  item_name text not null,
  location_type text not null default 'storage',
  location_name text not null default 'Oružarstvo Klaićeva',
  quantity integer not null default 0,
  note text,
  updated_at timestamptz not null default now(),
  constraint equipment_item_locations_qty_nonnegative check (quantity >= 0)
);

create unique index if not exists equipment_item_locations_unique
on public.equipment_item_locations (
  coalesce(equipment_legacy_id,''),
  lower(item_name),
  lower(location_type),
  lower(location_name)
);

-- Stock movement log for this and future legacy_return workflows.
create table if not exists public.sov_armory_stock_movements (
  id uuid primary key default gen_random_uuid(),
  event_key text unique,
  movement_type text not null,
  equipment_legacy_id text,
  item_name text not null,
  quantity numeric not null default 0,
  from_location_name text,
  to_location_name text not null default 'Oružarstvo Klaićeva',
  condition_status text,
  source_name text,
  source_row integer,
  note text,
  client_event_id text,
  created_by uuid default auth.uid(),
  created_at timestamptz not null default now()
);

create index if not exists sov_armory_stock_movements_type_idx on public.sov_armory_stock_movements(movement_type, created_at desc);
create index if not exists sov_armory_stock_movements_item_idx on public.sov_armory_stock_movements(equipment_legacy_id, item_name);

create table if not exists public.sov_armory_import_batches (
  import_key text primary key,
  source_name text not null,
  source_file text,
  source_location text not null default 'Oružarstvo Klaićeva',
  imported_rows integer not null default 0,
  ok_rows integer not null default 0,
  check_rows integer not null default 0,
  note text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create table if not exists public.sov_armory_import_backup_rows (
  id uuid primary key default gen_random_uuid(),
  import_key text not null,
  backup_reason text not null,
  equipment_legacy_id text,
  item_name text,
  row_data jsonb,
  created_at timestamptz not null default now()
);

-- 2) Location + categories.
