values ('LOC-KLAICEVA-ARMORY', 'Oružarstvo Klaićeva', 'Službeno trenutno stanje iz inventure Klaićeva 2026', 'storage')
on conflict (legacy_id) do update set
  name = excluded.name,
  description = excluded.description,
  type = excluded.type;

