insert into public.equipment_categories (legacy_id,name,description,type,sort_order,updated_at)
select legacy_id,name,description,type,sort_order,updated_at
from xls_categories
on conflict (legacy_id) do update set
  name = excluded.name,
  description = excluded.description,
  type = excluded.type,
  sort_order = excluded.sort_order,
  updated_at = now();

-- 3) Backup + supersede only previous XLS/import seed rows.
--    Ne briše ručne/nepoznate artikle i ne dira posudbe.
insert into public.sov_armory_import_backup_rows (import_key, backup_reason, equipment_legacy_id, item_name, row_data)
select
  'KLAICEVA-2026-OPENING-BALANCE',
  'before v2.1 opening balance supersede',
  e.legacy_id,
  e.name,
  to_jsonb(e)
from public.equipment_items e
where (
    coalesce(e.source_sheet,'') ilike '%SOV_oruzarstvo_jednostavna_popunjena_evidencija%'
    or coalesce(e.source_sheet,'') ilike '%Inventura Klaićeva 2026%'
    or coalesce(e.legacy_id,'') like 'KLAICEVA-2026-%'
  )
  and not exists (
    select 1 from public.sov_armory_import_backup_rows b
    where b.import_key = 'KLAICEVA-2026-OPENING-BALANCE'
      and b.equipment_legacy_id = e.legacy_id
      and b.backup_reason = 'before v2.1 opening balance supersede'
  );

update public.equipment_items
set
  status = 'superseded',
  availability = 'nedostupno',
  member_visible = false,
  quantity = 0,
  available = 0,
  updated_at = now(),
  internal_note = concat_ws(E'\n', nullif(internal_note,''), 'Superseded by Inventura Klaićeva 2026 opening balance import.')
where (
    coalesce(source_sheet,'') ilike '%SOV_oruzarstvo_jednostavna_popunjena_evidencija%'
    or coalesce(source_sheet,'') ilike '%Inventura Klaićeva 2026%'
    or coalesce(legacy_id,'') like 'KLAICEVA-2026-%'
  );

update public.equipment_item_locations
set quantity = 0,
    updated_at = now(),
    note = concat_ws(E'\n', nullif(note,''), 'Superseded by Inventura Klaićeva 2026 opening balance import.')
where (
    coalesce(equipment_legacy_id,'') in (
      select legacy_id from public.equipment_items
      where coalesce(status,'') = 'superseded'
        and (
          coalesce(source_sheet,'') ilike '%SOV_oruzarstvo_jednostavna_popunjena_evidencija%'
          or coalesce(source_sheet,'') ilike '%Inventura Klaićeva 2026%'
          or coalesce(legacy_id,'') like 'KLAICEVA-2026-%'
        )
    )
    or coalesce(note,'') ilike '%SOV_oruzarstvo_jednostavna_popunjena_evidencija%'
    or coalesce(note,'') ilike '%Inventura Klaićeva 2026%'
  );

