  quantity,loaned,available,minimum,status,availability,member_visible,internal_note,
  location_name,source_sheet,item_kind,code_required,physical_code_note,quantity_label,available_label,
  last_inventory_date,source_xls_row,xls_category,xls_subcategory,original_quantity_text,updated_at
)
select
  legacy_id,catalog_id,name,category_id,category_name,subcategory,unit,'bulk',
  quantity,0,available,null,status,availability,member_visible,internal_note,
  'Oružarstvo Klaićeva',source_sheet,item_kind,false,null,quantity_label,available_label,
  current_date,source_xls_row,xls_category,xls_subcategory,original_quantity_text,now()
from import_rows
on conflict (legacy_id) do update set
  catalog_id = excluded.catalog_id,
  name = excluded.name,
  category_id = excluded.category_id,
  category_name = excluded.category_name,
  subcategory = excluded.subcategory,
  unit = excluded.unit,
  tracking_type = excluded.tracking_type,
  quantity = excluded.quantity,
  loaned = excluded.loaned,
  available = excluded.available,
  minimum = excluded.minimum,
  status = excluded.status,
  availability = excluded.availability,
  member_visible = excluded.member_visible,
  internal_note = excluded.internal_note,
  location_name = excluded.location_name,
  source_sheet = excluded.source_sheet,
  item_kind = excluded.item_kind,
  code_required = excluded.code_required,
