update public.equipment_item_locations l
set quantity = greatest(0, round(coalesce(r.quantity,0)))::integer,
    note = concat('Opening balance: Inventura Klaićeva 2026; status=', r.condition_status, '; XLS red ', r.source_xls_row),
    updated_at = now()
from import_rows r
where coalesce(l.equipment_legacy_id,'') = coalesce(r.legacy_id,'')
  and lower(l.item_name) = lower(r.name)
  and lower(l.location_type) = 'storage'
  and lower(l.location_name) = lower('Oružarstvo Klaićeva');

