insert into public.sov_armory_stock_movements (
  event_key,movement_type,equipment_legacy_id,item_name,quantity,
  from_location_name,to_location_name,condition_status,source_name,source_row,note,client_event_id
)
select
  'OPENING-BALANCE-KLAICEVA-2026-' || lpad(source_xls_row::text, 4, '0'),
  'opening_balance',
  legacy_id,
  name,
  coalesce(quantity,0),
  null,
  'Oružarstvo Klaićeva',
  condition_status,
  'Inventura Klaićeva 2026',
  source_xls_row,
  internal_note,
  'KLAICEVA-2026-OPENING-' || lpad(source_xls_row::text, 4, '0')
from import_rows
on conflict (event_key) do update set
  equipment_legacy_id = excluded.equipment_legacy_id,
  item_name = excluded.item_name,
  quantity = excluded.quantity,
  condition_status = excluded.condition_status,
  source_name = excluded.source_name,
  source_row = excluded.source_row,
  note = excluded.note;

-- 7) Import batch metadata.
insert into public.sov_armory_import_batches (
  import_key,source_name,source_file,source_location,imported_rows,ok_rows,check_rows,note,created_at,updated_at
)
values (
  'KLAICEVA-2026-OPENING-BALANCE',
  'Inventura Klaićeva 2026',
  'sov_popis_iz_fotki_dopunjeno_crveno_nesigurno.xlsx',
  'Oružarstvo Klaićeva',
  174,
  106,
  68,
  'XLS inventura Klaićeva = početna istina. Stare posudbe se ne rekonstruiraju.',
  now(),
  now()
)
on conflict (import_key) do update set
  imported_rows = excluded.imported_rows,
  ok_rows = excluded.ok_rows,
  check_rows = excluded.check_rows,
  note = excluded.note,
  updated_at = now();

commit;

